import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) {
        Deque<Integer> nums = new ArrayDeque<>();
        nums.offerLast(20);
        nums.offerLast(30);
        nums.offerFirst(10);
        nums.offerFirst(5);
        System.out.println("Deque: " + nums);
        System.out.println("First: " + nums.peekFirst());
        System.out.println("Last: " + nums.peekLast());

        nums.push(1);
        System.out.println("After push: " + nums);

        String[] words = {"racecar", "stack"};
        for (String word : words) {
            System.out.println(word + ": " + isPalindrome(word));
        }
    }

    static boolean isPalindrome(String word) {
        Deque<Character> chars = new ArrayDeque<>();
        for (char c : word.toCharArray()) {
            chars.offerLast(c);
        }
        while (chars.size() > 1) {
            char first = chars.pollFirst();
            char last = chars.pollLast();
            if (first != last) {
                return false;
            }
        }
        return true;
    }
}

