import java.util.Collections;
import java.util.PriorityQueue;

public class Main {
    public static void main(String[] args) {
        int[] values = {5, 1, 8, 3, 2};

        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int v : values) {
            minHeap.offer(v);
        }
        System.out.println("Heap order: " + minHeap);
        System.out.println("Smallest: " + minHeap.peek());
        StringBuilder sorted = new StringBuilder();
        while (!minHeap.isEmpty()) {
            if (sorted.length() > 0) {
                sorted.append(' ');
            }
            sorted.append(minHeap.poll());
        }
        System.out.println("Sorted: " + sorted);

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int v : values) {
            maxHeap.offer(v);
        }
        for (int i = 0; i < 3; i++) {
            int top = maxHeap.poll();
            System.out.println("Large: " + top);
        }

        int[][] taskData = {{4, 2}, {1, 3}, {7, 1}, {2, 2}, {5, 3}};
        PriorityQueue<int[]> tasks = new PriorityQueue<>((a, b) -> {
            if (a[1] != b[1]) {
                return Integer.compare(a[1], b[1]);
            }
            return Integer.compare(a[0], b[0]);
        });
        for (int[] t : taskData) {
            tasks.offer(t);
        }
        System.out.println("Tasks: " + tasks.size());
        while (!tasks.isEmpty()) {
            int[] t = tasks.poll();
            System.out.println("Task " + t[0] + " priority " + t[1]);
        }
    }
}

